from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oscar.core.loading import get_model

OrderLine = get_model('order', 'Line')

class OrderLineCancellationView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, line_id):
        # Ensure the order line belongs to an order placed by the authenticated user
        try:
            line = OrderLine.objects.select_related('order').get(pk=line_id, order__user=request.user)
        except OrderLine.DoesNotExist:
            return Response({'error': 'Order line not found'}, status=status.HTTP_404_NOT_FOUND)

        if line.status in ['Cancelled', 'Refunded']:
            return Response({'error': 'Line already cancelled'}, status=status.HTTP_400_BAD_REQUEST)

        line.set_status('Cancelled')
        line.save()
        return Response({'status': 'Item cancelled successfully', 'line_id': line.id})
